use bevy::prelude::{Commands, MessageReader, Query};

use crate::effects;

/// 611.2a A continuous effect generated by the resolution of a spell or ability lasts as long as
/// stated by the spell or ability creating it (such as "until end of turn").
///
/// 613.4c Power- and/or toughness-changing effects are applied in layer 7c after all other
/// effects in layers 1 through 7b.
pub fn r611_2a_continuous_effects(
    mut modifications: MessageReader<effects::PowerToughnessModified>,
    mut commands: Commands,
    modifiers: Query<&effects::PowerToughnessModifier>,
) {
    for modification in modifications.read() {
        let current = modifiers.get(modification.target).copied().unwrap_or_default();
        commands.entity(modification.target).insert(effects::PowerToughnessModifier {
            power: current.power.saturating_add(modification.power),
            toughness: current.toughness.saturating_add(modification.toughness),
        });
    }
}

#[cfg(test)]
mod tests {
    use crate::damage;
    use crate::effects;
    use crate::mana;
    use crate::testing::*;
    use crate::{BATTLEFIELD, GRAVEYARD, HAND};

    #[test]
    fn test_usage() {
        let (mut game, [p1, p2]) = MockGame::new([
            P1.hand([GIANT_GROWTH]).battlefield([GRIZZLY_BEARS]).mana_pool(mana![G]),
            P2,
        ]);
        let [growth] = game.player(p1).cards_in(HAND).exactly::<1>(GIANT_GROWTH).unwrap();
        let [bears] = game.player(p1).cards_in(BATTLEFIELD).exactly::<1>(GRIZZLY_BEARS).unwrap();
        game.play([
            p1.cast(growth).targeting(bears).pass_priority(),
            p2.pass_priority(),
        ])
        .unwrap();
        let modifier =
            game.app.world().get::<effects::PowerToughnessModifier>(bears.into()).copied();
        assert_eq!(
            modifier,
            Some(effects::PowerToughnessModifier {
                power: 3,
                toughness: 3,
            })
        );
        assert_eq!(game.zone_of(growth), GRAVEYARD);
    }

    #[test]
    fn r611_2a_giant_growth_saves_a_creature_from_lethal_damage() {
        let (mut game, [p1, p2]) = MockGame::new([
            P1.hand([LIGHTNING_BOLT]).mana_pool(mana![R]),
            P2.hand([GIANT_GROWTH]).battlefield([GRIZZLY_BEARS]).mana_pool(mana![G]),
        ]);
        let [bolt] = game.player(p1).cards_in(HAND).exactly::<1>(LIGHTNING_BOLT).unwrap();
        let [growth] = game.player(p2).cards_in(HAND).exactly::<1>(GIANT_GROWTH).unwrap();
        let [bears] = game.player(p2).cards_in(BATTLEFIELD).exactly::<1>(GRIZZLY_BEARS).unwrap();

        game.play([
            p1.cast(bolt).targeting(bears).pass_priority(),
            p2.cast(growth).targeting(bears).pass_priority(),
            p1.pass_priority(),
            p1.pass_priority(),
            p2.pass_priority(),
        ])
        .unwrap();

        assert_eq!(game.zone_of(bears), BATTLEFIELD);
        let damage = game.app.world().get::<damage::Damage>(bears.into()).copied();
        assert_eq!(damage, Some(damage::Damage(3)));
        let modifier =
            game.app.world().get::<effects::PowerToughnessModifier>(bears.into()).copied();
        assert_eq!(
            modifier,
            Some(effects::PowerToughnessModifier {
                power: 3,
                toughness: 3,
            })
        );
    }
}
